            "founder": "Ivan Pavlov",
            "definition": "A learning process in which a previously neutral stimulus becomes associated with a meaningful stimulus to elicit a conditioned response.",
            "type": "Stimulus-Stimulus (S-S) learning"
          },
          "operant_conditioning": {
            "founder": "B.F. Skinner",
            "definition": "A learning process in which the strength of a behavior is modified by reinforcement or punishment following the behavior.",
            "type": "Stimulus-Response-Consequence (S-R-C) learning"
          }
        }
      },
      {
        "step": 2,
        "name": "Identify Core Components",
        "classical_conditioning": {
          "unconditioned_stimulus": "A stimulus that naturally and automatically triggers a response (e.g., food)",
          "unconditioned_response": "Natural, unlearned response to the unconditioned stimulus (e.g., salivation)",
          "conditioned_stimulus": "Previously neutral stimulus that becomes associated (e.g., bell)",
          "conditioned_response": "Learned response to the conditioned stimulus (e.g., salivation to bell)"
        },
        "operant_conditioning": {
          "reinforcement": "Consequence that increases likelihood of behavior (positive or negative)",
          "punishment": "Consequence that decreases likelihood of behavior (positive or negative)",
          "antecedent": "Environmental cue that signals the behavior will be reinforced/punished",
          "consequence": "Outcome following the behavior that shapes future behavior"
        }
      },
      {
        "step": 3,
        "name": "Compare Key Dimensions",
        "comparison_table": {
          "behavior_type": {
            "classical": "Involuntary/Reflexive (Respondent behavior)",
            "operant": "Voluntary/Emitted behavior"
          },
          "trigger_source": {
            "classical": "Behavior is elicited by a specific stimulus",
            "operant": "Behavior is emitted by the organism and shaped by consequences"
          },
          "learning_mechanism": {
            "classical": "Association between two stimuli",
            "operant": "Association between behavior and its consequences"
          },
          "temporal_focus": {
            "classical": "Before the response (antecedent stimuli)",
            "operant": "After the response (consequences)"
          },
          "role_of_organism": {
            "classical": "Passive recipient of stimulus pairing",
            "operant": "Active agent operating on the environment"
          }
        }
      },
      {
        "step": 4,
        "name": "Provide Illustrative Examples",
        "classical_conditioning_example": {
          "scenario": "Pavlov's dog experiment",
          "process": "Bell (neutral stimulus) + Food (unconditioned stimulus) → Salivation (response). After pairing, bell alone triggers salivation."
        },
        "operant_conditioning_example": {
          "scenario": "Skinner box with rat pressing lever",
          "process": "Rat presses lever (behavior) → Receives food pellet (positive reinforcement) → Increases likelihood of pressing lever again."
        }
      },
      {
        "step": 5,
        "name": "Highlight Applications",
