      },
      {
        "step": 6,
        "name": "Summarize Core Distinction",
        "key_takeaway": {
            "classical_conditioning": "Learning through association—organism learns that Stimulus A predicts Stimulus B.",
            "operant_conditioning": "Learning through consequences—organism learns that Behavior A leads to Consequence B.",
            "unifying_principle": "Both involve associative learning but differ in whether the association is between stimuli (classical) or between behavior and its outcomes (operant)."
